		}
	}

	void addWarning(String messageId, String messageArg) {
		int beg = -1, end = -1;
		if (ts != null) {
			beg = ts.tokenBeg;
			end = ts.tokenEnd - ts.tokenBeg;
		}
		addWarning(messageId, messageArg, beg, end);
	}

	void addWarning(String messageId, int position, int length) {
