	}

	public List<TypeInfo> types() {
		return types;
	}

	@Override
	public Class<?> asClass() {
		return TypeInfo.class;
	}

	@Override
	public TypeInfo or(TypeInfo info) {
		if (info instanceof JSOrTypeInfo) {
			JSOrTypeInfo other = (JSOrTypeInfo) info;
			List<TypeInfo> types1 = other.types();
			List<TypeInfo> list = new ArrayList<TypeInfo>(types.size() + types1.size());
			list.addAll(types);
			list.addAll(types1);
			return new JSOrTypeInfo(List.copyOf(list));
		} else {
			List<TypeInfo> list = new ArrayList<TypeInfo>(types.size() + 1);
			list.addAll(types);
			list.add(info);
			return new JSOrTypeInfo(List.copyOf(list));
		}
