		for (int i = 0; i < types.size(); i++) {
			if (i != 0) {
				ctx.appendSpace(sb);
				sb.append('|');
				ctx.appendSpace(sb);
			}

			ctx.append(sb, types.get(i));
		}
	}

	@Override
	public void collectContainedComponentClasses(Collection<Class<?>> classes) {
		for (TypeInfo type : types) {
			type.collectContainedComponentClasses(classes);
		}
	}

	@Override
	public boolean equals(Object other) {
		if (!(other instanceof JSOrTypeInfo)) {
			return false;
		}
		JSOrTypeInfo that = (JSOrTypeInfo) other;
		return Objects.equals(types, that.types);
	}

	@Override
	public int hashCode() {
		int hash = 0;
		hash = 31 * hash + Objects.hashCode(types);
		return hash;
	}
}

